public class TextMessage
{
    public string Text { get; set; } = string.Empty;
}

public class TextMessageHandler : IHandleMessages<TextMessage>
{
    public async Task Handle(TextMessage message)
    {
        Console.WriteLine($"Got text: {message.Text}");
    }
}

// Configure and start
var bus = Configure.With(new BuiltinHandlerActivator())
    .Transport(t => t.UseRabbitMq("amqp://guest:guest@localhost", "my-queue"))
    .Start();

await bus.Send(new TextMessage { Text = "Hello Rebus!" });
